209	     * Show the current status of the field.
210	     * 
211	     * @param field The field whose status is to be displayed.
212	     */
213	    public void showStatus(Field field)
214	    {
215	        if(!isVisible()) {
216	            setVisible(true);
217	        }
218	            
219	        stepLabel.setText(STEP_PREFIX + Time.getStep());
220	        timeLabel.setText(TIME_PREFIX + getTimeString());
221	        weatherLabel.setText(WEATHER_PREFIX + Weather.getWeather() + "  ");
222	        
223	        fieldView.preparePaint();
224	        
225	        // Used to tally up the respective counts.
226	        int numberOfInfected = 0;
227	        int numberOfImmune = 0;
228	        
229	        for(int row = 0; row < field.getDepth(); row++) 
230	        {
231	            for(int col = 0; col < field.getWidth(); col++) 
232	            {
233	                Animal animal = (Animal) field.getObjectAt(row, col, Animal.class);
234	                Plant plant = (Plant) field.getObjectAt(row, col, Plant.class);
235	                
236	                if(animal != null) 
237	                {
238	                    fieldView.drawMark(col, row, getColor(animal.getClass()));
239	                    
240	                    // Update the infected and immune counts
241	                    if (animal.getIsInfected())
242	                    {
243	                        numberOfInfected++;
244	                    }
245	                    
246	                    if (animal.getIsImmune())
247	                    {
248	                        numberOfImmune++;
249	                    }
250	                }
251	                // Only show the plant if an animal is not present
252	                else if(plant != null) 
253	                {
254	                    fieldView.drawMark(col, row, getColor(plant.getClass()));
255	                }
256	                else 
257	                {
258	                    Color emptyColor = EMPTY_COLOR;
259	                    fieldView.drawMark(col, row, emptyColor);
260	                    fieldView.setBackground(emptyColor);
261	                }
262	                
263	            }
264	        }
265	
266	        infectedLabel.setText(INFECTED_PREFIX + numberOfInfected);
267	        immuneLabel.setText(IMMUNE_PREFIX + numberOfImmune);
268	
269	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
270	        fieldView.repaint();
271	    }
