304	    /**
305	     * Provide a graphical view of a rectangular field. This is 
306	     * a nested class (a class defined inside a class) which
307	     * defines a custom component for the user interface. This
308	     * component displays the field.
309	     */
310	    private class FieldView extends JPanel
311	    {
312	        private final int GRID_VIEW_SCALING_FACTOR = 6;
313	
314	        private int gridWidth, gridHeight;
315	        private double xScale, yScale;
316	        Dimension size;
317	        private Graphics g;
318	        private Image fieldImage;
319	
320	        /**
321	         * Create a new FieldView component.
322	         */
323	        public FieldView(int height, int width)
324	        {
325	            gridHeight = height;
326	            gridWidth = width;
327	            size = new Dimension(0, 0);
328	        }
329	
330	        /**
331	         * Tell the GUI manager how big we would like to be.
332	         * 
333	         * @return Dimensions
334	         */
335	        public Dimension getPreferredSize()
336	        {
337	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
338	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
339	        }
340	
341	        /**
342	         * Prepare for a new round of painting. Since the component
343	         * may be resized, compute the scaling factor again.
344	         */
345	        public void preparePaint()
346	        {
347	            if(! size.equals(getSize())) {  // if the size has changed...
348	                size = getSize();
349	                fieldImage = fieldView.createImage(size.width, size.height);
350	                g = fieldImage.getGraphics();
351	            
352	                xScale = size.width / gridWidth;
353	                if(xScale < 1) {
354	                    xScale = GRID_VIEW_SCALING_FACTOR;
355	                }
356	                yScale = size.height / gridHeight;
357	                if(yScale < 1) {
358	                    yScale = GRID_VIEW_SCALING_FACTOR;
359	                }
360	                
361	                // Makes sure that the grid remains in proportion
362	                // (the grid squares remain as squares)
363	                if(xScale > yScale) {
364	                    xScale = yScale;
365	                }
366	                else if(xScale < yScale) {
367	                    yScale = xScale;
368	                }
369	            }
370	        }
371	        
372	        /**
373	         * Paint on grid location on this field in a given color.
374	
375	         * @param x X-position to draw the mark
376	         * @param y Y-position to draw the mark
377	         * @param color The colour to draw the mark
378	         */
379	        private void drawMark(int x, int y, Color color)
380	        {
381	            g.setColor(color);
382	            g.fillRect((int)(x * xScale), (int)(y * yScale) , (int)(xScale - 1.0), (int)(yScale - 1.0));
383	        }
384	
385	        /**
386	         * The field view component needs to be redisplayed. Copy the
387	         * internal image to screen.
388	         * 
389	         * @param g Graphics
390	         */
391	        public void paintComponent(Graphics g)
392	        {
393	            if(fieldImage != null) 
394	            {
395	                Dimension currentSize = getSize();
396	                
397	                if(size.equals(currentSize)) 
398	                {
399	                    g.drawImage(fieldImage, 0, 0, null);
400	                }
401	                else 
402	                {
403	                    // Rescale the previous image.
404	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
405	                }
406	            }
407	        }
408	    }
409	}

