296	        for(int row = 0; row < field.getDepth(); row++) 
297	        {
298	            for(int col = 0; col < field.getWidth(); col++) 
299	            {
300	                Animal animal = field.getObjectAt(row, col, Animal.class);
301	                Plant plant = field.getObjectAt(row, col, Plant.class);
302	
303	                if(animal != null) 
304	                {
305	                    fieldView.drawCell(col, row, getColor(animal.getClass()));
306	
307	                    if (animal.getIsInfected())
308	                    {
309	                        numberOfInfected++;
310	                    }
311	
312	                    if (animal.getIsImmune())
313	                    {
314	                        numberOfImmune++;
315	                    }
316	                }
317	                else if(plant != null) 
318	                {
319	                    fieldView.drawCell(col, row, getColor(plant.getClass()));
320	                }
321	                else 
322	                {
323	                    fieldView.drawCell(col, row, EMPTY_COLOR);
324	                }
325	            }
326	        }
327	
328	        fieldView.endFrame();
329	        return new FieldStatus(numberOfInfected, numberOfImmune);
330	    }
